package net.civeira.phylax.features.document.theme.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.document.theme.domain.Theme;
import net.civeira.phylax.features.document.theme.domain.event.ThemeEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ThemeEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ThemeEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final Theme entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
